 return defs.map(([id,field,x,y,width,height,font_size,bold,align])=>{const type:InvoiceCanvasElement['type']=id==='logo'?'logo':id==='total-highlight'?'shape':'field';const item=makeCanvasElement(id,type,field,x,y,width,height);item.font_size=font_size;item.bold=bold;item.align=(align||'left') as InvoiceCanvasElement['align'];if(id==='total-highlight')item.background='#edf2f4';return item;});
};
