const invoiceLabelFields:(keyof InvoiceLabels)[]=['invoice_title','bill_to','invoice_number','invoice_date','due_date','item','unit_price','quantity','gst','total','subtotal','gst_included','payment_instruction','bank','account_name','account_number','payment_gst','payment_note','credit_line','company_gst','reference','order_id','description','site_address','order_total','amount_due'];
