const invoiceFieldGroups:{title:string;keys:InvoiceFieldKey[]}[]=[{title:'Company details',keys:['company_name','company_gst','company_address']},{title:'Customer details',keys:['customer_company','customer_contact','customer_address','customer_phone','customer_email']},{title:'Invoice heading',keys:['invoice_title','invoice_number','invoice_reference','invoice_date','due_date']},{title:'Totals',keys:['subtotal','gst_total','invoice_total']},{title:'Payment details',keys:['payment_heading','payment_bank','payment_account_name','payment_account_number','payment_note','payment_gst']}];
