async function load(){ loading.value=true; error.value=''; try { const [c,i,r]=await Promise.all([request<Customer[]>('operations/customers'),request<Invoice[]>('operations/invoices'),request<{credits:Credit[]}>('operations/rebates')]); customers.value=c; invoices.value=i; credits.value=r.credits; if(props.admin) settings.value=await request<Settings>('operations/settings'); fillSettings(); } catch(e){error.value=e instanceof Error?e.message:String(e)} finally{loading.value=false} }
function fillSettings(){ if(!settings.value)return; Object.assign(payment,settings.value.payment_details); Object.assign(template,settings.value.invoice_template); template.layout_style=settings.value.invoice_template.layout_style||'reference_aa0013'; if(!Object.values(payment).some(Boolean))Object.assign(payment,{bank_name:'ASB',account_name:'VCG Group Ltd',account_number:'12-3233-0714884-00',reference_note:''}); if(!template.gst_number)template.gst_number='139-745-388'; template.invoice_labels={...defaultInvoiceLabels,...(settings.value.invoice_template.invoice_labels||{})}; template.invoice_columns={unit_price:settings.value.invoice_template.invoice_columns?.unit_price??true,quantity:settings.value.invoice_template.invoice_columns?.quantity??true,gst:settings.value.invoice_template.invoice_columns?.gst??true}; template.invoice_field_settings=Object.fromEntries((['deposit','balance','manual'] as const).map(kind=>[kind,{...fieldDefaults(kind),...(settings.value?.invoice_template.invoice_field_settings?.[kind]||{}),item_columns:settings.value?.invoice_template.invoice_field_settings?.[kind]?.item_columns||fieldDefaults(kind).item_columns}])) as InvoiceTemplate['invoice_field_settings']; const saved=template.invoice_designs||{} as InvoiceDesigns; for(const kind of ['deposit','balance','manual'] as const){ const current=saved[kind]?.blocks||[]; const byId=new Map(current.map(block=>[block.id,block])); const ordered=current.map(block=>({...block,label:blockLabels[block.id]||block.id,area:block.area||blockDefaultAreas[block.id],align:block.area?block.align:blockDefaultAlignments[block.id]||block.align})); for(const id of blockIds)if(!byId.has(id))ordered.push({id,label:blockLabels[id],enabled:true,align:blockDefaultAlignments[id]||'left',width:220,area:blockDefaultAreas[id]}); saved[kind]={blocks:ordered,elements:Array.isArray(saved[kind]?.elements)?saved[kind].elements:defaultCanvasElements()}; } template.invoice_designs=saved; if(!selectedCanvasElement.value)selectedElementId.value=activeCanvasElements.value[0]?.id||''; }
function sortBy(key:typeof sortKey.value){ if(sortKey.value===key)sortDesc.value=!sortDesc.value; else {sortKey.value=key;sortDesc.value=key!=='company'} }
async function created(invoice:Invoice){ newInvoiceOpen.value=false; await load(); void openPreview(invoice); }
async function openPreview(invoice:Invoice){ error.value=''; previewInvoice.value=invoice; try { const response=await request<{html:string}>(`operations/invoices/${encodeURIComponent(invoice.id)}/mail-preview`); previewHtml.value=response.html; } catch(e){previewHtml.value=''; error.value=e instanceof Error?e.message:String(e)} }
async function send(invoice:Invoice){ busy.value=true; error.value=''; notice.value=''; try{ const sent=await request<Invoice>(`operations/invoices/${encodeURIComponent(invoice.id)}/send`,{}); notice.value=`${sent.invoice_number||sent.id}: ${sent.status}`; await load(); previewInvoice.value=null; }catch(e){error.value=e instanceof Error?e.message:String(e)}finally{busy.value=false} }
async function markReceived(invoice:Invoice){ const note=window.prompt('Confirm the payment has arrived. Add a note (optional):','Payment received'); if(note===null)return; busy.value=true; error.value=''; try{await request(`operations/invoices/${encodeURIComponent(invoice.id)}/received`,{note:note.trim()||'Payment received'}); await load();}catch(e){error.value=e instanceof Error?e.message:String(e)}finally{busy.value=false} }
async function setClaim(credit:Credit,event:Event){ const value=(event.target as HTMLSelectElement).value; busy.value=true; error.value=''; try{await request(`operations/rebates/${encodeURIComponent(credit.id)}/claim-status`,{claim_status:value}); const result=await request<{credits:Credit[]}>('operations/rebates'); credits.value=result.credits;}catch(e){error.value=e instanceof Error?e.message:String(e); await load()}finally{busy.value=false} }
function paymentPayload(){ return { account_name:payment.account_name, bank_name:payment.bank_name, account_number:payment.account_number, reference_note:payment.reference_note }; }
async function saveSettings(){ if(!props.admin)return; settingsBusy.value=true; error.value=''; notice.value=''; try{settings.value=await request<Settings>('operations/settings',{payment_details:paymentPayload(),invoice_template:templatePayload()}); fillSettings(); notice.value='Invoice templates and payment details saved.'; settingsOpen.value=false;}catch(e){error.value=e instanceof Error?e.message:String(e)}finally{settingsBusy.value=false} }
function moveBlock(index:number,delta:number){ const blocks=activeBlocks.value; const target=index+delta; if(target<0||target>=blocks.length)return; const next=[...blocks]; [next[index],next[target]]=[next[target],next[index]]; template.invoice_designs[templateKind.value].blocks=next; }
function placeBlock(blockId:string,area:InvoiceArea){ const block=activeBlocks.value.find(item=>item.id===blockId); if(block)block.area=area; draggingBlock.value=''; }
function changeBlock(block:InvoiceDesignBlock,key:'align'|'width'|'enabled'|'area',value:string|number|boolean){ const current=activeBlocks.value.find(item=>item.id===block.id); if(!current)return; if(key==='enabled'&&(block.id==='order_lines'||block.id==='totals'))return; Object.assign(current,{[key]:value}); }
function toggleItemColumn(id:string,event:Event){const selected=template.invoice_field_settings[templateKind.value].item_columns;const enabled=(event.target as HTMLInputElement).checked;if(id==='amount'&&!enabled){(event.target as HTMLInputElement).checked=true;return}if(enabled&&!selected.includes(id))selected.push(id);if(!enabled)template.invoice_field_settings[templateKind.value].item_columns=selected.filter(key=>key!==id)}
function moveItemColumn(index:number,delta:number){const columns=template.invoice_field_settings[templateKind.value].item_columns;const target=index+delta;if(target<0||target>=columns.length)return;[columns[index],columns[target]]=[columns[target],columns[index]];}
const itemColumnPosition=(id:string)=>template.invoice_field_settings[templateKind.value].item_columns.indexOf(id);
function addCanvasElement(type:InvoiceCanvasElement['type'],field=''){const id=`${type}-${Math.random().toString(36).slice(2,9)}`;const element=makeCanvasElement(id,type,type==='shape'?'':field,84,Math.min(980,120+activeCanvasElements.value.length*18),type==='logo'?200:260,type==='shape'?52:38);if(type==='text')element.text='Your text';if(type==='shape'){element.shape=field==='line'?'line':'rectangle';element.background=element.shape==='line'?'':'#edf2f4';element.border_color='#405969';element.border_width=1;}activeCanvasElements.value.push(element);selectedElementId.value=id;}
function clearCanvas(){if(!window.confirm('Clear every element from this invoice template? You can restore the starter layout before saving.'))return;template.invoice_designs[templateKind.value].elements=[];selectedElementId.value='';}
function resetCanvas(){template.invoice_designs[templateKind.value].elements=defaultCanvasElements();selectedElementId.value='invoice-title';}
function removeCanvasElement(){if(!selectedCanvasElement.value)return;template.invoice_designs[templateKind.value].elements=activeCanvasElements.value.filter(element=>element.id!==selectedElementId.value);selectedElementId.value=activeCanvasElements.value[0]?.id||'';}
function canvasLabel(element:InvoiceCanvasElement){if(element.type==='text')return element.text;if(element.type==='shape')return '';if(element.type==='logo')return 'VERA logo';return fieldOptions.find(([key])=>key===element.field)?.[1]||element.field;}
function canvasElementTitle(element:InvoiceCanvasElement|null){if(!element)return '';return element.type==='field'?(fieldOptions.find(([key])=>key===element.field)?.[1]||'Invoice field'):element.type==='text'?'Text box':element.type==='logo'?'Logo':element.shape==='line'?'Line':'Shape';}
function canvasSample(element:InvoiceCanvasElement){if(element.type==='text')return element.text;if(element.type==='shape'||element.type==='logo')return '';const samples:Record<string,string>={company_name:template.company_name||'VERA Shading Solutions',company_gst:template.gst_number?`GST No. ${template.gst_number}`:'GST number',company_address:template.company_address||'Company address',invoice_title:template.invoice_labels.invoice_title,invoice_number:`${template.invoice_labels.invoice_number} INV-00042`,invoice_reference:'AA-METCALFE',invoice_date:`${template.invoice_labels.invoice_date}: 12 Nov 2026`,due_date:`${template.invoice_labels.due_date}: 17 Nov 2026`,customer_label:template.invoice_labels.bill_to,customer_company:'Auckland Shutters',customer_contact:'Jeremy',customer_address:'Auckland, New Zealand',customer_phone:'021 000 0000',customer_email:'customer@example.com',order_summary:'AA-METCALFE · Living room shutters · Auckland     NZD 1,201.06',order_id:'AA-METCALFE',description:'Living room shutters',site_address:'Auckland',order_total:'NZD 2,001.77',gst:'15%',amount_due:'NZD 1,201.06',subtotal:`${template.invoice_labels.subtotal}: NZD 1,044.40`,gst_total:`${template.invoice_labels.gst_included} (15%): NZD 156.66`,invoice_total:`${template.invoice_labels.total}: NZD 1,201.06`,payment_heading:template.invoice_labels.payment_instruction,payment_details:[payment.bank_name,payment.account_name,payment.account_number,payment.reference_note].filter(Boolean).join('\n')||'Bank details',invoice_note:templateKind.value==='deposit'?template.deposit_note:templateKind.value==='balance'?template.balance_note:'Amounts include GST.',footer:template.footer||'Thank you for your business.'};return samples[element.field]||'Dynamic value';}
function canvasElementStyle(element:InvoiceCanvasElement){return {left:`${element.x}px`,top:`${element.y}px`,width:`${element.width}px`,height:element.type==='shape'&&element.shape==='line'?'0px':`${element.height}px`,fontFamily:element.font_family,fontSize:`${element.font_size}px`,fontWeight:element.bold?'700':'400',fontStyle:element.italic?'italic':'normal',color:element.color,textAlign:element.align,background:element.background||'transparent',border:element.type==='shape'&&element.shape==='line'?'0':`${element.border_width}px solid ${element.border_color}`,borderTop:element.type==='shape'&&element.shape==='line'?`${Math.max(1,element.border_width)}px solid ${element.border_color}`:undefined};}
function startCanvasGesture(event:PointerEvent,element:InvoiceCanvasElement,mode:'move'|'resize'='move'){if(event.button!==0||editingTextId.value===element.id||previewExpanded.value)return;if(event.shiftKey){selectedIds.value=selectedIds.value.includes(element.id)?selectedIds.value.filter(id=>id!==element.id):[...selectedIds.value,element.id];selectedElementId.value=element.id;return;}if(!selectedIds.value.includes(element.id))selectedIds.value=[element.id];event.stopPropagation();selectedElementId.value=element.id;canvasGesture={id:element.id,mode,clientX:event.clientX,clientY:event.clientY,x:element.x,y:element.y,width:element.width,height:element.height};(event.currentTarget as HTMLElement).setPointerCapture?.(event.pointerId);}
function moveCanvasGesture(event:PointerEvent){if(!canvasGesture)return;const target=activeCanvasElements.value.find(element=>element.id===canvasGesture?.id);if(!target)return;const dx=(event.clientX-canvasGesture.clientX)/templatePreviewScale.value,dy=(event.clientY-canvasGesture.clientY)/templatePreviewScale.value;if(canvasGesture.mode==='move'){target.x=Math.max(0,Math.min(794-target.width,Math.round(canvasGesture.x+dx)));target.y=Math.max(0,Math.min(1123-target.height,Math.round(canvasGesture.y+dy)));snapCanvasElement(target);}else{target.width=Math.max(12,Math.min(794-target.x,Math.round(canvasGesture.width+dx)));target.height=Math.max(8,Math.min(1123-target.y,Math.round(canvasGesture.height+dy)));}}
function stopCanvasGesture(){canvasGesture=null;guideX.value=null;guideY.value=null;recordCanvasHistory();}
function setCanvasBackground(element:InvoiceCanvasElement,event:Event){element.background=(event.target as HTMLInputElement).checked?'#edf2f4':'';}
function templatePayload(){ return { layout_style:template.layout_style, company_name:template.company_name, gst_number:template.gst_number, company_address:template.company_address, footer:template.footer, deposit_note:template.deposit_note, balance_note:template.balance_note, invoice_labels:{...template.invoice_labels}, invoice_columns:{...template.invoice_columns}, invoice_field_settings:Object.fromEntries((['deposit','balance','manual'] as const).map(kind=>[kind,{...template.invoice_field_settings[kind],item_columns:[...template.invoice_field_settings[kind].item_columns]}])), invoice_designs:Object.fromEntries((['deposit','balance','manual'] as const).map(kind=>[kind,{blocks:template.invoice_designs[kind].blocks.map(({id,enabled,align,width,area})=>({id,enabled,align,width,area})),elements:template.invoice_designs[kind].elements.map(element=>({...element}))}])) }; }
async function updateReferencePreview(){if(!settingsOpen.value||template.layout_style!=='reference_aa0013')return;const requestId=++referenceRequest;referenceBusy.value=true;try{const result=await request<{html:string}>('operations/invoice-template-preview',{kind:templateKind.value,payment_details:paymentPayload(),invoice_template:templatePayload()});if(requestId===referenceRequest)referenceHtml.value=result.html;}catch(e){error.value=e instanceof Error?e.message:String(e)}finally{if(requestId===referenceRequest)referenceBusy.value=false;}}
watch([settingsOpen,templateKind,template,payment],()=>{window.clearTimeout(referenceTimer);if(settingsOpen.value&&template.layout_style==='reference_aa0013')referenceTimer=window.setTimeout(updateReferencePreview,300);},{deep:true});
watch(()=>template.layout_style,()=>nextTick(()=>{templatePreviewObserver?.disconnect();fitInvoicePage();if(templatePreviewCanvas.value){templatePreviewObserver=new ResizeObserver(fitInvoicePage);templatePreviewObserver.observe(templatePreviewCanvas.value)}}));
function fitInvoicePage(){const canvas=templatePreviewCanvas.value;if(!canvas)return;const width=(canvas.clientWidth-48)/794,height=(canvas.clientHeight-40)/1123;templatePreviewScale.value=zoomMode.value==='width'?Math.max(.1,width):zoomMode.value==='page'?Math.max(.1,Math.min(width,height)):Number(zoomMode.value);}
function recordCanvasHistory(){if(restoringHistory||!settingsOpen.value)return;const value=JSON.stringify(activeCanvasElements.value);if(canvasHistory.value[historyIndex.value]===value)return;canvasHistory.value=canvasHistory.value.slice(0,historyIndex.value+1);canvasHistory.value.push(value);if(canvasHistory.value.length>60)canvasHistory.value.shift();historyIndex.value=canvasHistory.value.length-1;}
function travelHistory(delta:number){window.clearTimeout(historyTimer);recordCanvasHistory();const index=historyIndex.value+delta;if(index<0||index>=canvasHistory.value.length)return;restoringHistory=true;historyIndex.value=index;template.invoice_designs[templateKind.value].elements=JSON.parse(canvasHistory.value[index]);restoringHistory=false;}
watch(()=>JSON.stringify(activeCanvasElements.value),()=>{if(restoringHistory||!settingsOpen.value)return;window.clearTimeout(historyTimer);historyTimer=window.setTimeout(recordCanvasHistory,350)},{flush:'sync'});
watch([settingsOpen,templateKind],()=>{window.clearTimeout(historyTimer);canvasHistory.value=[];historyIndex.value=-1;selectedIds.value=[];editingTextId.value='';recordCanvasHistory();});
watch(zoomMode,()=>nextTick(fitInvoicePage));
watch(previewExpanded,value=>{if(value)zoomMode.value='page';});
function snapCanvasElement(element:InvoiceCanvasElement){guideX.value=null;guideY.value=null;const xs=[48,397,746],ys=[48,561,1075];for(const other of activeCanvasElements.value){if(other.id!==element.id){xs.push(other.x,other.x+other.width/2,other.x+other.width);ys.push(other.y,other.y+other.height/2,other.y+other.height);}}for(const value of xs){for(const offset of [0,element.width/2,element.width])if(Math.abs(element.x+offset-value)<5){element.x=Math.max(0,Math.min(794-element.width,Math.round(value-offset)));guideX.value=value;break;}if(guideX.value!==null)break;}for(const value of ys){for(const offset of [0,element.height/2,element.height])if(Math.abs(element.y+offset-value)<5){element.y=Math.max(0,Math.min(1123-element.height,Math.round(value-offset)));guideY.value=value;break;}if(guideY.value!==null)break;}}
function alignCanvas(direction:'left'|'center'|'right'){const items=activeCanvasElements.value.filter(item=>selectedIds.value.includes(item.id)||item.id===selectedElementId.value);if(!items.length)return;const left=items.length>1?Math.min(...items.map(item=>item.x)):48;const right=items.length>1?Math.max(...items.map(item=>item.x+item.width)):746;for(const item of items)item.x=Math.round(direction==='left'?left:direction==='right'?right-item.width:(left+right-item.width)/2);recordCanvasHistory();}
function duplicateCanvas(){const item=selectedCanvasElement.value;if(!item)return;const copy={...item,id:`copy-${Math.random().toString(36).slice(2,9)}`,x:Math.min(794-item.width,item.x+16),y:Math.min(1123-item.height,item.y+16)};activeCanvasElements.value.push(copy);selectedElementId.value=copy.id;selectedIds.value=[copy.id];recordCanvasHistory();}
function layerCanvas(front:boolean){const items=activeCanvasElements.value;const index=items.findIndex(item=>item.id===selectedElementId.value);if(index<0)return;const [item]=items.splice(index,1);if(front)items.push(item);else items.unshift(item);recordCanvasHistory();}
function editorKey(event:KeyboardEvent){if((event.target as HTMLElement).closest('input,textarea,select,[contenteditable]'))return;if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='z'){event.preventDefault();travelHistory(event.shiftKey?1:-1);}else if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='d'){event.preventDefault();duplicateCanvas();}else if(event.key==='Delete'){event.preventDefault();removeCanvasElement();}}

watch([settingsOpen,previewExpanded],async ([open])=>{await nextTick();templatePreviewObserver?.disconnect();if(!open)return;fitInvoicePage();if(templatePreviewCanvas.value){templatePreviewObserver=new ResizeObserver(fitInvoicePage);templatePreviewObserver.observe(templatePreviewCanvas.value)}});
async function openPdf(invoice:Invoice){ try{ const response=await fetch(`/api/operations/invoices/${encodeURIComponent(invoice.id)}/pdf`,{headers:session.token?{Authorization:`Bearer ${session.token}`}:{}}); if(!response.ok)throw new Error('Could not open invoice PDF'); const url=URL.createObjectURL(await response.blob()); window.open(url,'_blank','noopener'); setTimeout(()=>URL.revokeObjectURL(url),60000);}catch(e){error.value=e instanceof Error?e.message:String(e)} }
onMounted(async()=>{await load();const id=String(route.query.invoice||'');const invoice=invoices.value.find(row=>row.id===id);if(invoice)await openPreview(invoice);});
</script>

<template>
  <main class="accounting">
    <header class="page-head"><div><p class="eyebrow">VERA · FINANCE</p><h1>Accounting</h1><p>Manage customer invoices and monthly rebates from the same records used in the customer portal.</p></div><div class="head-actions"><button v-if="pane==='invoices' && admin" class="primary" @click="startInvoiceCreation">＋ New invoice</button><button v-if="pane==='invoices' && admin" class="secondary" @click="settingsOpen=true">Invoice settings</button><button class="secondary" @click="load" :disabled="loading">Refresh</button></div></header>
    <p v-if="error" class="notice error" role="alert">{{ error }}</p><p v-if="notice" class="notice success" role="status">{{ notice }}</p>
    <nav class="tabs" role="tablist"><button role="tab" :aria-selected="pane==='invoices'" :class="{active:pane==='invoices'}" @click="pane='invoices'">Invoice <span>{{ invoices.length }}</span></button><button role="tab" :aria-selected="pane==='rebates'" :class="{active:pane==='rebates'}" @click="pane='rebates'">Rebate <span>{{ credits.length }}</span></button></nav>
    <section v-if="pane==='invoices'" class="panel">
      <header class="panel-head"><div><h2>Invoices</h2><p>Invoice history, due dates and payment status.</p></div><strong>{{ invoiceRows.length }} / {{ invoices.length }}</strong></header>
      <div class="filters"><label>Search<input v-model="query" type="search" placeholder="Invoice, customer or order" /></label><label>Type<select v-model="kindFilter"><option value="">All types</option><option value="deposit">Deposit</option><option value="balance">Balance</option><option value="manual">Manual</option></select></label><label>Created from<input v-model="createdFrom" type="date" /></label><label>Created to<input v-model="createdTo" type="date" /></label></div>
      <div v-if="loading" class="empty">Loading invoices…</div><div v-else class="table-scroll"><table><thead><tr><th>Invoice</th><th><button type="button" @click="sortBy('created_at')">Created ↕</button></th><th><div class="invoice-header-filter"><button type="button" @click="sortBy('company')">Customer ↕</button><select v-model="customerFilter" aria-label="Filter invoices by customer"><option value="">All customers</option><option v-for="c in customers" :key="c.customer_id" :value="String(c.customer_id)">{{ c.company }}</option></select></div></th><th>Type</th><th><button type="button" @click="sortBy('due_date')">Due date ↕</button></th><th><button type="button" @click="sortBy('amount')">Amount</button></th><th>Paid date</th><th><div class="invoice-header-filter"><button type="button" @click="sortBy('payment_status')">Payment status ↕</button><select v-model="statusFilter" aria-label="Filter invoices by payment status"><option value="">All statuses</option><option value="draft">Draft</option><option value="unpaid">Unpaid</option><option value="paid">Paid</option></select></div></th><th>Actions</th></tr></thead><tbody><tr v-for="invoice in invoiceRows" :key="invoice.id"><td><strong>{{ invoice.invoice_number||invoice.id }}</strong></td><td>{{ localDate(invoice.created_at) }}</td><td>{{ customerName(invoice.customer_id) }}</td><td>{{ invoiceKind(invoice.kind) }}</td><td>{{ localDate(invoice.due_date) }}</td><td>{{ money(invoice.amount,invoice.currency) }}</td><td>{{ localDate(invoice.received_at) }}</td><td><span class="status" :class="paymentStatus(invoice)" :title="invoice.status">{{ paymentStatus(invoice) }}</span></td><td class="invoice-actions"><div class="invoice-row-actions"><button class="text" @click="openPreview(invoice)">Preview</button><button class="text" @click="openPdf(invoice)">PDF</button><button v-if="invoice.status==='draft' || invoice.status==='not_configured' || invoice.status==='demo_suppressed'" class="text" :disabled="busy" @click="send(invoice)">Send</button><button v-if="invoice.kind!=='deposit' && paymentStatus(invoice)!=='paid' && invoice.status!=='draft'" class="text" :disabled="busy" @click="markReceived(invoice)">Mark paid</button><small v-if="invoice.kind==='deposit' && paymentStatus(invoice)!=='paid'" title="Confirm deposit payment in Orders">Via Orders</small></div></td></tr><tr v-if="!loading&&!invoiceRows.length"><td colspan="9" class="empty">No invoices match these filters.</td></tr></tbody></table></div>
    </section>
    <section v-else class="panel">
      <header class="panel-head"><div><h2>Monthly rebates</h2><p>Automatically calculated from deposit paid dates. Claim status is shared with each customer’s My Rebate page.</p></div><strong>{{ creditRows.length }} credits</strong></header>
      <div class="filters"><label>Search<input v-model="creditQuery" type="search" placeholder="Customer or month" /></label><label>Claim status<select v-model="creditStatus"><option value="">All statuses</option><option value="unclaimed">Unclaimed</option><option value="partially_claimed">Partially claimed</option><option value="claimed">Claimed</option></select></label></div>
      <div v-if="loading" class="empty">Loading rebates…</div><div v-else class="rebate-groups"><details v-for="group in creditGroups" :key="group.customer_id" class="rebate-group" open><summary><strong>{{ group.company }}</strong><span>{{ group.credits.length }} months</span><b>{{ money(group.credits.reduce((sum,c)=>sum+Number(c.amount||0),0)) }} earned</b></summary><div class="table-scroll"><table><thead><tr><th>Month</th><th>Rebate earned</th><th>Claimed</th><th>Available</th><th>Claimed on invoice</th><th>Status</th></tr></thead><tbody><tr v-for="credit in group.credits" :key="credit.id"><td>{{ credit.month }}</td><td>{{ money(credit.amount,credit.currency) }}</td><td>{{ money(credit.used,credit.currency) }}</td><td>{{ money(credit.remaining,credit.currency) }}</td><td><span v-if="credit.allocations?.length">{{ credit.allocations.map(a=>a.invoice_number||a.invoice_id).filter(Boolean).join(', ') }}</span><span v-else>—</span></td><td><select :value="credit.claim_status||'unclaimed'" :disabled="!admin || busy || !!credit.allocations?.some(a=>a.invoice_id)" @change="setClaim(credit,$event)"><option value="unclaimed">Unclaimed</option><option value="claimed">Claimed</option><option v-if="credit.claim_status==='partially_claimed'" value="partially_claimed">Partially claimed</option></select></td></tr></tbody></table></div></details><p v-if="!creditGroups.length" class="empty">No rebates match these filters.</p></div>
    </section>
    <div v-if="newInvoiceOpen" class="overlay" @click.self="newInvoiceOpen=false"><section class="dialog"><header><h2>New invoice</h2><button class="close" @click="newInvoiceOpen=false">×</button></header><div v-if="invoiceCreationStep==='customer'" class="invoice-customer-step"><p>Select the customer once. Their details will carry through to the invoice.</p><label>Find customer<input v-model="invoiceCustomerSearch" type="search" placeholder="Search company name" /></label><label>Customer<select v-model="invoiceCustomerId"><option value="">Choose a customer</option><option v-for="customer in invoiceCustomers" :key="customer.customer_id" :value="String(customer.customer_id)">{{customer.company}}</option></select></label><div class="invoice-type-options"><button type="button" :disabled="!invoiceCustomerId" @click="invoiceCreationStep='items'"><strong>Manual invoice</strong><span>Enter item names and GST-inclusive amounts.</span></button><button type="button" :disabled="!invoiceCustomerId" @click="openCustomerOrders()"><strong>Balance invoice</strong><span>Select this customer's orders, add charges and apply available rebates.</span></button><button type="button" :disabled="!invoiceCustomerId" @click="openCustomerOrders(true)"><strong>Deposit invoice</strong><span>Generated automatically for each order when you approve it. Open orders awaiting review.</span></button></div></div><ManualInvoiceForm v-else :customers="customers" :selected-customer-id="Number(invoiceCustomerId)" locale="en" @created="created" /></section></div>
    <div v-if="settingsOpen" class="overlay invoice-designer-overlay" @click.self="settingsOpen=false"><section class="dialog settings-dialog designer-dialog" tabindex="-1" @keydown="editorKey" :class="{'preview-expanded':previewExpanded}"><header><div><p class="eyebrow">ACCOUNTING · INVOICE</p><h2>Invoice templates</h2><p class="dialog-subtitle">Invoice layout matched to your Invoice AA0013 PDF. Customer, dates, orders and totals fill automatically.</p></div><button class="close" @click="settingsOpen=false">×</button></header><form @submit.prevent="saveSettings"><nav class="template-tabs" aria-label="Invoice template type"><button v-for="kind in (['deposit','balance','manual'] as const)" :key="kind" type="button" :class="{active:templateKind===kind}" @click="templateKind=kind">{{ kind==='deposit'?'Deposit invoice':kind==='balance'?'Balance invoice':'Manual invoice' }}</button><select v-model="template.layout_style" aria-label="Invoice layout"><option value="reference_aa0013">Your PDF layout</option><option value="canvas">Advanced canvas</option></select></nav><div v-if="template.layout_style==='canvas'" class="workbench-toolbar">
<button type="button" @click="addCanvasElement('text')">Text box</button><button type="button" :class="{active:insertOpen}" @click="insertOpen=!insertOpen">Insert data</button><button type="button" @click="addCanvasElement('logo')">Logo</button><button type="button" @click="addCanvasElement('shape')">Rectangle</button><button type="button" @click="addCanvasElement('shape','line')">Line</button><span class="toolbar-divider"></span><button type="button" :disabled="historyIndex<1" @click="travelHistory(-1)">Undo</button><button type="button" :disabled="historyIndex>=canvasHistory.length-1" @click="travelHistory(1)">Redo</button><button type="button" @click="invoiceDataOpen=true">Invoice details</button><select v-model="zoomMode" aria-label="Canvas zoom"><option value="page">Fit page</option><option value="width">Fit width</option><option value="0.75">75%</option><option value="1">100%</option><option value="1.25">125%</option><option value="1.5">150%</option></select><button type="button" @click="previewExpanded=!previewExpanded">{{previewExpanded?'Edit template':'Print preview'}}</button>
</div><div v-if="insertOpen" class="field-drawer"><header><strong>Insert invoice data</strong><button type="button" @click="insertOpen=false">Close</button></header><input v-model="fieldSearch" placeholder="Search fields" /><section v-for="group in fieldGroups" :key="group.name"><h4 v-if="group.fields.length">{{group.name}}</h4><button v-for="[key,label] in group.fields" :key="key" type="button" draggable="true" @dragstart="canvasFieldToAdd=key" @click="addCanvasElement('field',key);insertOpen=false">{{label}}</button></section></div>
<section v-if="template.layout_style==='reference_aa0013'" class="reference-workspace">
<div class="reference-toolbar"><strong>Invoice AA0013 layout</strong><span>{{referenceBusy?'Updating preview...':'Automatic order and customer information'}}</span><button type="button" class="secondary" @click="invoiceDataOpen=true">Edit company and payment details</button><select v-model="zoomMode" aria-label="Preview zoom"><option value="page">Fit page</option><option value="width">Fit width</option><option value="1">100%</option><option value="1.25">125%</option></select></div>
<div ref="templatePreviewCanvas" class="reference-viewport"><div class="reference-stage" :style="{width:`${794*templatePreviewScale}px`,height:`${1123*templatePreviewScale}px`}"><iframe v-if="referenceHtml" class="reference-paper-frame" :srcdoc="referenceHtml" title="Invoice matched to your PDF" scrolling="no" sandbox="allow-same-origin" :style="{transform:`scale(${templatePreviewScale})`}" /><p v-else>Preparing your invoice preview...</p></div></div>
</section><div v-else class="designer-layout canvas-designer-layout">
  <aside class="canvas-tools">

    <section v-if="selectedCanvasElement" class="canvas-properties"><div class="property-title"><strong>{{ canvasElementTitle(selectedCanvasElement) }}</strong><button type="button" @click="removeCanvasElement">Delete</button></div><label v-if="selectedCanvasElement.type==='text'">Text<textarea v-model="selectedCanvasElement.text" rows="3" maxlength="2000" /></label><label v-if="selectedCanvasElement.type==='field'">Content<select v-model="selectedCanvasElement.field"><option v-for="[key,label] in fieldOptions" :key="key" :value="key">{{ label }}</option></select></label>
      <div class="selection-actions"><button type="button" @click="duplicateCanvas">Duplicate</button><button type="button" @click="layerCanvas(true)">Bring forward</button><button type="button" @click="layerCanvas(false)">Send back</button></div><div class="selection-actions"><button type="button" @click="alignCanvas('left')">Align left</button><button type="button" @click="alignCanvas('center')">Center</button><button type="button" @click="alignCanvas('right')">Align right</button></div><div class="property-grid"><label>X<input v-model.number="selectedCanvasElement.x" type="number" min="0" max="794" /></label><label>Y<input v-model.number="selectedCanvasElement.y" type="number" min="0" max="1123" /></label><label>Width<input v-model.number="selectedCanvasElement.width" type="number" min="12" max="794" /></label><label>Height<input v-model.number="selectedCanvasElement.height" type="number" min="8" max="1123" /></label></div>
      <template v-if="selectedCanvasElement.type==='text'||selectedCanvasElement.type==='field'"><div class="property-grid"><label>Font<select v-model="selectedCanvasElement.font_family"><option>Arial</option><option>Georgia</option><option>Times New Roman</option><option>Verdana</option><option>Courier New</option></select></label><label>Size<input v-model.number="selectedCanvasElement.font_size" type="number" min="6" max="72" /></label></div><div class="property-style-row"><label>Text color<input v-model="selectedCanvasElement.color" type="color" /></label><label><input v-model="selectedCanvasElement.bold" type="checkbox" /> Bold</label><label><input v-model="selectedCanvasElement.italic" type="checkbox" /> Italic</label><label>Align<select v-model="selectedCanvasElement.align"><option value="left">Left</option><option value="center">Center</option><option value="right">Right</option></select></label></div></template>
      <div v-if="selectedCanvasElement.type!=='logo'" class="property-style-row"><label><input type="checkbox" :checked="!!selectedCanvasElement.background" @change="setCanvasBackground(selectedCanvasElement,$event)" /> Background</label><input v-if="selectedCanvasElement.background" v-model="selectedCanvasElement.background" type="color" aria-label="Background color" /><label>Border<input v-model.number="selectedCanvasElement.border_width" type="number" min="0" max="8" /></label><input v-if="selectedCanvasElement.border_width" v-model="selectedCanvasElement.border_color" type="color" aria-label="Border color" /></div>
    </section><p v-else class="canvas-help">Select an item on the page to edit it. Drag items to position them and use the corner handle to resize.</p>

